import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long x = nextLong(), y = nextLong(), a = nextLong(), b = nextLong();
        // Walk backwards from the target: the previous point is unique.
        while (a >= x && b >= y && !(a == x && b == y)) {
            if (a > b) a -= b;
            else b -= a;
        }
        System.out.println(a == x && b == y ? "Yes" : "No");
    }
}

